// Web Audio engine (J3). Everything is generated by code. Graph:
//   voices (water, wind, rain, crickets, birds, soft music notes)  ->  bus ambience / music     effects -> bus fx
//   lofi music (J6 part C): one buffer per bar (made by code, audio/lofiRender.js) -> lofi gain -> tape low-pass -> bus music
//   real music (J6 part D): recorded CC0 tracks, one decoded buffer each -> track gain (normalisation + fades) -> real gain -> bus music
//   buses -> master (gain) -> compressor (limiter) -> speakers          (+ an optional AnalyserNode on the output, tests only)
//
// Rules kept here (ARCHITECTURE section 7):
//   - the AudioContext is created by start(), which main.js calls from a click or a key press (never before a gesture);
//   - nothing is sudden: every change goes through setTargetAtTime or a ramp; the master rises over 4 s;
//   - at most data.budget.maxNodes nodes alive at once: a voice that does not fit is skipped, never the effects;
//     a voice whose target stays 0 for 2 s is stopped and its nodes freed; buffers are made once and looped (no worklet);
//   - mute falls in 0.3 s, then the context is suspended; the context is also suspended when the tab is hidden.
// `makeContext` is injected so that the graph can be tested in Node with a tiny fake context.

import audioData from '../data/audio.js';
import { volumeGain } from '../core/audioMix.js';
import { whiteLoop, brownLoop, rainLoop, cricketsLoop } from './noise.js';
import { createComposer } from '../core/lofi.js';
import { mulberry32 } from '../core/rng.js';
import { createBarRenderer } from './lofiRender.js';
import { createPlaylist } from '../core/playlist.js';
import { fadeCurve, trackTimes } from '../core/crossfade.js';
import { loadTrackBytes, decodeBytes } from './trackLoader.js';

const LOOP_VOICES = ['water', 'wind', 'rain', 'crickets'];

/**
 * @param {{makeContext:()=>object|null, rng:()=>number, data?:object, analyser?:boolean, timers?:{set:Function, clear:Function, after:Function},
 *   loadBytes?:(url:string)=>Promise<ArrayBuffer>, decode?:(ctx:object, bytes:ArrayBuffer, rate:number)=>Promise<object>}} o
 */
export function createAudioEngine({ makeContext, rng, data = audioData, analyser = false, timers = { set: (f, ms) => setInterval(f, ms), clear: (id) => clearInterval(id), after: (f, ms) => setTimeout(f, ms) }, loadBytes = loadTrackBytes, decode = decodeBytes, perfNow = () => (typeof performance !== 'undefined' ? performance.now() : Date.now()) }) {
  let ctx = null;
  let started = false;
  let unavailable = false;
  let muted = false;
  let hidden = false;
  let timer = null;
  let tap = null;
  let master = null;
  let comp = null;
  let delay = null;
  let feedback = null;
  const bus = {};
  const volumes = { ambience: data.defaults.ambience, fx: data.defaults.fx, music: data.defaults.music };
  let levels = { water: 0, wind: 0, birds: 0, crickets: 0, rain: 0, music: 0, scale: 'dusk' };
  const voices = new Map();
  const buffers = {};
  const alive = new Set();
  let peakNodes = 0;
  let activeSources = 0;
  let peakSources = 0;
  let nextBird = 0;
  let nextNote = 0;
  const notes = new Set();
  const counts = { sfx: 0, skipped: 0, notes: 0, chirps: 0, lofiBars: 0, lofiLate: 0, lofiSkipped: 0, realRequested: 0, realLoaded: 0, realFailed: 0, realStarted: 0 };
  let style = data.defaultStyle;
  let styleChangedAt = -1e9;
  let ticked = false; // a style chosen before the first scheduler tick (the saved choice, at start) is not a change: no soft notes then
  let lofiRenderMsMax = 0;
  // lofi state: the chain (gain + tape low-pass, 2 nodes), the bar being made, when the next bar is due, the buffer sources alive (at most 3)
  const lofi = { gain: null, tape: null, composer: null, renderer: null, bar: null, nextStart: null, sources: new Set(), offAt: null, ducked: false, last: -1, tc: 1, renderMs: 0, curveUntil: -1, curveIn: false };
  // real-music state (J6 part D). `entries`: the tracks scheduled or playing (at most 2: the one ending and the one starting); `ready`: a track
  // fetched and decoded, waiting for its turn; `loading`: the track being fetched; `base`: the generated style heard before the tracks
  // (null at the start of a session: nothing was heard); `token` invalidates an answer that comes after the style was left.
  const tracksById = Object.fromEntries(data.real.tracks.map((x) => [x.id, x]));
  const real = { out: null, entries: [], playlist: null, loading: null, ready: null, base: null, audibleSince: null, level: -1, curveUntil: -1, leaving: false, offAt: null, failedAll: false, token: 0, decodedBytesMax: 0, fetchMsMax: 0, decodeMsMax: 0, firstRequestAt: null };

  const between = (r) => r[0] + rng() * (r[1] - r[0]);
  const track = (n) => {
    alive.add(n);
    if (alive.size > peakNodes) peakNodes = alive.size;
    return n;
  };
  const free = (n) => {
    try {
      n.disconnect();
    } catch (e) {
      /* already disconnected */
    }
    alive.delete(n);
  };
  const room = (cost, forSfx) => alive.size + cost <= data.budget.maxNodes - (forSfx ? 0 : data.budget.sfxReserve);
  const now = () => ctx.currentTime;

  function build() {
    master = track(ctx.createGain());
    master.gain.value = 0;
    comp = track(ctx.createDynamicsCompressor());
    const L = data.limiter;
    comp.threshold.value = L.threshold;
    comp.knee.value = L.knee;
    comp.ratio.value = L.ratio;
    comp.attack.value = L.attack;
    comp.release.value = L.release;
    master.connect(comp);
    comp.connect(ctx.destination);
    if (analyser) {
      tap = track(ctx.createAnalyser());
      tap.fftSize = 32768;
      comp.connect(tap);
    }
    for (const name of ['ambience', 'fx', 'music']) {
      const g = track(ctx.createGain());
      g.gain.value = volumeGain(volumes[name]) * data.trim[name];
      g.connect(master);
      bus[name] = g;
    }
  }

  function bufferFor(name) {
    if (buffers[name]) return buffers[name];
    // made at a low fixed rate (22.05 kHz, enough for every voice: the highest content is the crickets at 4.6 kHz): 4 times less work
    // than at the 96 kHz some machines use, so starting a voice never makes the game hitch; the context resamples when playing
    const sr = data.bufferRateHz;
    const cfg = data.voices[name];
    let channels;
    if (name === 'water') channels = [brownLoop(rng, Math.floor(sr * cfg.seconds))];
    else if (name === 'wind') channels = [whiteLoop(rng, Math.floor(sr * cfg.seconds))];
    else if (name === 'rain') channels = [rainLoop(rng, sr, cfg.seconds)];
    else channels = cricketsLoop(rng, sr, cfg.seconds);
    const buf = ctx.createBuffer(channels.length, channels[0].length, sr);
    channels.forEach((c, i) => buf.getChannelData(i).set(c));
    buffers[name] = buf;
    return buf;
  }

  // ---------------------------------------------------------------- looping voices
  function startVoice(name) {
    const cost = name === 'crickets' ? 2 : 3;
    if (!room(cost, false)) return; // retried at the next tick, when something has ended
    const cfg = data.voices[name];
    const src = track(ctx.createBufferSource());
    src.buffer = bufferFor(name);
    src.loop = true;
    const nodes = [src];
    let head = src;
    let filter = null;
    if (name !== 'crickets') {
      filter = track(ctx.createBiquadFilter());
      if (name === 'water') {
        filter.type = 'lowpass';
        filter.frequency.value = cfg.lowpassHz;
      } else if (name === 'wind') {
        filter.type = 'bandpass';
        filter.Q.value = cfg.q;
        filter.frequency.value = between(cfg.hz);
      } else {
        filter.type = 'highpass';
        filter.frequency.value = cfg.highpassHz;
      }
      src.connect(filter);
      head = filter;
      nodes.push(filter);
    }
    const g = track(ctx.createGain());
    g.gain.value = 0;
    head.connect(g);
    g.connect(bus.ambience);
    nodes.push(g);
    src.start(now(), rng() * src.buffer.duration);
    activeSources++;
    peakSources = Math.max(peakSources, activeSources);
    voices.set(name, { name, src, filter, gain: g, nodes, last: -1, zeroSince: null, nextEvent: now(), mult: 1 });
  }
  function stopVoice(v) {
    try {
      v.src.stop();
    } catch (e) {
      /* already stopped */
    }
    activeSources--;
    v.nodes.forEach(free);
    voices.delete(v.name);
  }
  function driveVoices(t) {
    for (const name of LOOP_VOICES) {
      const cfg = data.voices[name];
      const target = (levels[name] || 0) * cfg.gain;
      let v = voices.get(name);
      if (target > 0.002) {
        if (!v) {
          startVoice(name);
          v = voices.get(name);
          if (!v) continue;
        }
        v.zeroSince = null;
        let eff = target;
        if (name === 'water' && t >= v.nextEvent) {
          v.mult = 0.72 + 0.28 * rng();
          v.nextEvent = t + cfg.wobbleEveryS;
          v.last = -1;
        }
        if (name === 'water') eff = target * v.mult;
        if (name === 'wind' && t >= v.nextEvent) {
          v.filter.frequency.setTargetAtTime(between(cfg.hz), t, 2);
          v.nextEvent = t + cfg.glideEveryS;
        }
        if (Math.abs(eff - v.last) > 0.0015) {
          v.gain.gain.setTargetAtTime(eff, t, name === 'water' ? 1.5 : data.levelTcS);
          v.last = eff;
        }
      } else if (v) {
        if (v.last !== 0) {
          v.gain.gain.setTargetAtTime(0, t, data.levelTcS);
          v.last = 0;
        }
        if (v.zeroSince === null) v.zeroSince = t;
        else if (t - v.zeroSince > data.idleStopS + 4 * data.levelTcS) stopVoice(v); // silent for 2 s after the fade has ended
      }
    }
  }

  // ---------------------------------------------------------------- transient sounds
  function osc(type, hz, startT, stopT, nodesOut) {
    const o = track(ctx.createOscillator());
    o.type = type;
    o.frequency.setValueAtTime(hz, startT);
    nodesOut.push(o);
    o.start(startT);
    o.stop(stopT);
    activeSources++;
    peakSources = Math.max(peakSources, activeSources);
    return o;
  }
  function release(nodesList, source) {
    source.onended = () => {
      activeSources--;
      nodesList.forEach(free);
    };
  }
  /** One oscillator through its own gain envelope into `dest`. Returns false when there is no room. */
  function tone({ type = 'sine', hz, partials = null, hz2 = null, at, attack, hold, decayTc, stop, peak, dest, also = null, forSfx }) {
    const list = partials || [hz];
    if (!room(1 + list.length, forSfx)) {
      counts.skipped++;
      return false;
    }
    const nodes = [];
    const oscs = list.map((f) => osc(type, f, at, stop, nodes));
    const o = oscs[0];
    if (hz2) o.frequency.exponentialRampToValueAtTime(hz2, at + hold);
    const g = track(ctx.createGain());
    nodes.push(g);
    g.gain.setValueAtTime(0, at);
    g.gain.linearRampToValueAtTime(peak, at + attack);
    g.gain.setTargetAtTime(0, at + attack + (hold > attack ? hold - attack : 0), decayTc);
    for (const x of oscs) x.connect(g);
    g.connect(dest);
    if (also) g.connect(also);
    // the nodes are freed when the LAST oscillator has ended (all stop at the same time)
    let left = oscs.length;
    for (const x of oscs) {
      x.onended = () => {
        activeSources--;
        if (--left === 0) nodes.forEach(free);
      };
    }
    return true;
  }
  function noiseBurst({ seconds, f0, f1, type, q = 1, peak, attack, decayTc, forSfx }) {
    if (!room(3, forSfx)) {
      counts.skipped++;
      return false;
    }
    const t = now() + 0.01;
    const src = track(ctx.createBufferSource());
    src.buffer = bufferFor('wind');
    src.loop = true;
    const f = track(ctx.createBiquadFilter());
    f.type = type;
    f.Q.value = q;
    f.frequency.setValueAtTime(f0, t);
    if (f1) f.frequency.exponentialRampToValueAtTime(f1, t + seconds * 0.8);
    const g = track(ctx.createGain());
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(peak, t + attack);
    g.gain.setTargetAtTime(0, t + attack, decayTc);
    src.connect(f);
    f.connect(g);
    g.connect(bus.fx);
    src.start(t, rng() * src.buffer.duration);
    src.stop(t + seconds);
    activeSources++;
    peakSources = Math.max(peakSources, activeSources);
    release([src, f, g], src);
    return true;
  }

  function sfxPloc(k) {
    const c = data.sfx.ploc;
    const t = now() + 0.01;
    tone({ hz: c.hz[0], hz2: c.hz[1], at: t, attack: 0.01, hold: c.durS, decayTc: 0.05, stop: t + c.durS + 0.3, peak: c.gain * k, dest: bus.fx, forSfx: true });
  }
  function sfxChime(k, delayS) {
    const c = data.sfx.chime;
    const t = now() + 0.01 + delayS;
    tone({ partials: c.hz, at: t, attack: 0.01, hold: 0.02, decayTc: c.durS / 4, stop: t + c.durS * 1.6, peak: (c.gain * k) / 2, dest: bus.fx, forSfx: true });
  }
  const SFX = {
    cast() {
      const c = data.sfx.cast;
      noiseBurst({ seconds: c.seconds, f0: c.hz[0], f1: c.hz[1], type: 'bandpass', q: 1.2, peak: c.gain, attack: 0.08, decayTc: 0.12, forSfx: true });
    },
    splash() {
      const c = data.sfx.splash;
      noiseBurst({ seconds: c.seconds, f0: c.hz, f1: 500, type: 'lowpass', peak: c.gain, attack: 0.005, decayTc: 0.07, forSfx: true });
    },
    reel() {
      const c = data.sfx.reel;
      noiseBurst({ seconds: c.seconds, f0: c.hz[0], f1: c.hz[1], type: 'bandpass', q: 1, peak: c.gain, attack: 0.1, decayTc: 0.12, forSfx: true });
    },
    bite() {
      sfxPloc(1);
      sfxChime(1, 0.12);
    },
    'bite-soft'() {
      sfxPloc(0.5);
      sfxChime(0.5, 0.12);
    },
    catch() {
      const c = data.sfx.catch;
      c.notes.forEach((hz, i) => {
        const t = now() + 0.01 + i * c.stepS;
        tone({ hz, at: t, attack: 0.02, hold: 0.03, decayTc: c.durS / 4, stop: t + c.durS * 1.5, peak: c.gain, dest: bus.fx, forSfx: true });
      });
    },
    click() {
      const c = data.sfx.click;
      const t = now() + 0.005;
      tone({ hz: c.hz, at: t, attack: 0.004, hold: 0.01, decayTc: c.durS / 3, stop: t + c.durS + 0.1, peak: c.gain, dest: bus.fx, forSfx: true });
    },
  };

  // ---------------------------------------------------------------- lofi music: a bar is made in pieces, then played as one buffer at an exact time
  /** The generated style that is meant to be heard now: the chosen one; with the tracks chosen, the style heard before them until they play. */
  function genStyle() {
    if (style !== 'real') return style;
    if (real.audibleSince !== null) return null; // the tracks play: the generated style is fading out
    if (real.failedAll) return real.base || data.defaultStyle; // the tracks could not be loaded: back to the generated music, silently
    return real.base;
  }
  const lofiWanted = () => genStyle() === 'lofi' && levels.music >= 0.05;
  const lofiTarget = () => data.lofi.gain * Math.min(1, levels.music / 0.75) * (lofi.ducked ? data.lofi.duckGain : 1);
  function ensureLofiChain() {
    if (lofi.gain) return true;
    if (!room(2, false)) return false;
    lofi.gain = track(ctx.createGain());
    lofi.gain.gain.value = 0;
    lofi.tape = track(ctx.createBiquadFilter());
    lofi.tape.type = 'lowpass';
    lofi.tape.frequency.value = data.lofi.tapeHz;
    lofi.tape.Q.value = 0.5;
    lofi.gain.connect(lofi.tape);
    lofi.tape.connect(bus.music);
    lofi.last = -1;
    lofi.tc = data.lofi.fadeInTc;
    return true;
  }
  function applyLofiLevel(t, tc) {
    if (t < lofi.curveUntil) return; // a cross-fade curve is running on this gain: nothing else is scheduled on top of it
    const target = lofiTarget();
    if (Math.abs(target - lofi.last) < 0.002) return;
    if (lofi.curveIn) {
      // coming after the recorded tracks: rise on the equal-power curve while they fall on its twin
      lofi.curveIn = false;
      lofi.gain.gain.setValueCurveAtTime(fadeCurve('in', 128, target), t, data.real.crossS);
      lofi.curveUntil = t + data.real.crossS;
      lofi.last = target;
      lofi.tc = data.levelTcS;
      return;
    }
    lofi.gain.gain.setTargetAtTime(target, t, tc || lofi.tc);
    lofi.last = target;
    lofi.tc = data.levelTcS;
  }
  function startLofiBar(t) {
    // the music may use the nodes kept for effects (one source per bar): a chirp is skipped before a bar is. When even that is not possible
    // the finished bar waits for the next tick (counted); if its time has passed it starts late, on the next beat.
    if (!room(1, true)) {
      counts.lofiSkipped++;
      return;
    }
    const r = lofi.renderer;
    const bar = lofi.bar;
    lofi.renderer = null;
    lofi.bar = null;
    lofi.renderMs = 0;
    const buf = ctx.createBuffer(1, r.length, r.sampleRate);
    buf.getChannelData(0).set(r.result);
    let when = lofi.nextStart;
    if (when === null) when = t + data.lofi.startDelayS;
    else if (when < t + 0.02) {
      when = t + 0.05; // the scheduler was late (a long task, a throttled timer): the loop restarts on the next beat
      counts.lofiLate++;
    }
    const src = track(ctx.createBufferSource());
    src.buffer = buf;
    src.connect(lofi.gain);
    src.start(when);
    src.stop(when + buf.duration + 0.05);
    activeSources++;
    peakSources = Math.max(peakSources, activeSources);
    const entry = { src, ended: false };
    lofi.sources.add(entry);
    src.onended = () => {
      if (entry.ended) return;
      entry.ended = true;
      activeSources--;
      free(src);
      lofi.sources.delete(entry);
    };
    if (lofi.nextStart === null && real.out && real.audibleSince !== null) lofi.curveIn = true; // the first bar after the tracks
    lofi.nextStart = when + bar.barS;
    counts.lofiBars++;
  }
  function teardownLofi() {
    for (const e of lofi.sources) {
      if (e.ended) continue;
      e.ended = true;
      try {
        e.src.stop();
      } catch (err) {
        /* not started or already stopped */
      }
      activeSources--;
      free(e.src);
    }
    lofi.sources.clear();
    if (lofi.gain) free(lofi.gain);
    if (lofi.tape) free(lofi.tape);
    lofi.gain = null;
    lofi.tape = null;
    lofi.renderer = null;
    lofi.bar = null;
    lofi.nextStart = null;
    lofi.offAt = null;
    lofi.curveUntil = -1;
    lofi.curveIn = false;
  }
  function scheduleLofi(t) {
    const c = data.lofi;
    if (lofiWanted()) {
      lofi.offAt = null;
      if (!ensureLofiChain()) return;
      // the fade-in starts when the first bar is scheduled (not when the chain is made: making the first bar takes a second)
      if (lofi.nextStart !== null) applyLofiLevel(t, lofi.ducked ? 0.04 : 0);
      if (!lofi.renderer) {
        if (lofi.nextStart !== null && lofi.nextStart - t >= c.aheadBarS) return;
        if (!lofi.composer) lofi.composer = createComposer({ rng: mulberry32(Math.floor(rng() * 4294967296)) });
        lofi.bar = lofi.composer.nextBar(levels.scale);
        lofi.renderer = createBarRenderer(lofi.bar, { seed: 1 + counts.lofiBars + counts.lofiSkipped });
      }
      const t0 = perfNow();
      const finished = lofi.renderer.done || lofi.renderer.step(lofi.nextStart === null ? c.firstBarBudgetMs : c.renderBudgetMs, perfNow);
      lofi.renderMs += perfNow() - t0;
      if (finished) {
        lofiRenderMsMax = Math.max(lofiRenderMsMax, lofi.renderMs);
        startLofiBar(t);
      }
    } else if (lofi.gain) {
      lofi.renderer = null;
      lofi.bar = null;
      lofi.nextStart = null;
      if (lofi.last !== 0) {
        lofi.gain.gain.setTargetAtTime(0, t, c.fadeOutTc);
        lofi.last = 0;
      }
      if (lofi.offAt === null) lofi.offAt = t + c.offAfterS;
      else if (t >= lofi.offAt) teardownLofi();
    }
  }
  /** The tracks start to play: the lofi chain falls on the equal-power curve while they rise (the soft notes just stop being started). */
  function releaseLofi(when) {
    if (!lofi.gain || lofi.last <= 0) return;
    const g = lofi.gain.gain;
    const cur = Math.max(0, lofi.last);
    g.cancelScheduledValues(when);
    g.setValueAtTime(cur, when);
    g.setValueCurveAtTime(fadeCurve('out', 128, cur), when + 0.01, data.real.crossS);
    lofi.curveUntil = when + 0.01 + data.real.crossS;
    lofi.last = 0;
  }
  function duckLofi(s) {
    if (!lofi.gain || now() < lofi.curveUntil) return;
    lofi.ducked = true;
    applyLofiLevel(now(), 0.04);
    setTimeoutLike(s, () => {
      lofi.ducked = false;
      if (lofi.gain && lofiWanted()) applyLofiLevel(now(), 0.25);
    });
  }

  // ---------------------------------------------------------------- real music: recorded tracks, one decoded buffer each, in a shuffled endless row
  // Nothing is asked from the network before this runs, and this runs only when: the context exists (a gesture was made), the style
  // is 'real', the sound is not muted. A track is fetched and decoded about 50 s before the previous one ends (so at most 2 decoded
  // buffers live: the one playing and the next), started at an exact audio time, and cross-faded with the one before it.
  const trackLoadable = () => !muted && ctx && ctx.state === 'running';
  function genReady(t) {
    // real -> generated: the tracks play on until the new style is heard (soft: at once; lofi: its first bar is scheduled), then they fall
    if (style === 'soft') return true;
    return lofi.nextStart !== null || t - styleChangedAt > data.real.leaveWaitS;
  }
  function startLoad() {
    const id = real.playlist.next();
    if (id === null) return;
    const trk = tracksById[id];
    const token = real.token;
    const t0 = perfNow();
    real.loading = id;
    counts.realRequested++;
    if (real.firstRequestAt === null) real.firstRequestAt = ctx.currentTime;
    let p;
    try {
      p = Promise.resolve(loadBytes(trk.url));
    } catch (e) {
      p = Promise.reject(e);
    }
    p.then((bytes) => {
      const t1 = perfNow();
      real.fetchMsMax = Math.max(real.fetchMsMax, t1 - t0);
      return Promise.resolve(decode(ctx, bytes, trk.decodeRate)).then((buf) => {
        real.decodeMsMax = Math.max(real.decodeMsMax, perfNow() - t1);
        return buf;
      });
    }).then(
      (buf) => {
        if (token !== real.token) return; // the style was left in the meantime: the answer is dropped
        if (!buf || !(buf.duration > 2)) throw new Error('empty track');
        real.loading = null;
        real.ready = { id, buf, gain: trk.gain };
        counts.realLoaded++;
        real.decodedBytesMax = Math.max(real.decodedBytesMax, buf.length * buf.numberOfChannels * 4);
      },
      () => failTrack(id, token),
    ).catch(() => failTrack(id, token));
  }
  function failTrack(id, token) {
    if (token !== real.token || real.loading !== id) return;
    real.loading = null;
    real.playlist.fail(id);
    counts.realFailed++;
  }
  function placeReady(t) {
    const r = real.ready;
    const last = real.entries[real.entries.length - 1];
    const times = trackTimes(r.buf.duration, data.real.crossS);
    let when;
    if (!last) when = t + data.real.startDelayS;
    else {
      when = last.start + last.times.nextAtS;
      if (when > t + data.real.scheduleAheadS) return; // the nodes are made shortly before the track starts
      if (when < t + 0.05) when = t + 0.05; // late (a slow network): it starts as soon as it can, from silence
    }
    if (!real.out) {
      if (!room(3, true)) return;
      real.out = track(ctx.createGain());
      real.out.gain.value = 0;
      real.out.connect(bus.music);
      real.level = -1;
    } else if (!room(2, true)) return;
    real.ready = null;
    const src = track(ctx.createBufferSource());
    src.buffer = r.buf;
    const g = track(ctx.createGain());
    g.gain.value = 0;
    src.connect(g);
    g.connect(real.out);
    const peak = r.gain;
    g.gain.setValueCurveAtTime(fadeCurve('in', 128, peak), when, times.fadeInS);
    g.gain.setValueCurveAtTime(fadeCurve('out', 128, peak), when + times.nextAtS, times.fadeOutS);
    src.start(when);
    activeSources++;
    peakSources = Math.max(peakSources, activeSources);
    const entry = { id: r.id, src, g, start: when, times, duration: r.buf.duration, ended: false };
    real.entries.push(entry);
    counts.realStarted++;
    src.onended = () => {
      if (entry.ended) return;
      entry.ended = true;
      activeSources--;
      free(src);
      free(g);
      real.entries = real.entries.filter((e) => e !== entry);
      if (real.entries.length === 0 && real.audibleSince !== null && !real.leaving) real.audibleSince = null; // the row has run dry (nothing left to play)
    };
    if (real.audibleSince === null) {
      real.audibleSince = when;
      releaseLofi(when);
    }
  }
  function applyRealLevel(t) {
    const target = Math.min(1, levels.music / 0.75);
    if (Math.abs(target - real.level) < 0.002) return;
    if (real.level < 0) real.out.gain.setValueAtTime(target, t);
    else real.out.gain.setTargetAtTime(target, t, data.levelTcS);
    real.level = target;
  }
  function beginLeaveReal(t) {
    const g = real.out.gain;
    const cur = Math.max(0, real.level);
    real.leaving = true;
    g.cancelScheduledValues(t);
    g.setValueAtTime(cur, t);
    g.setValueCurveAtTime(fadeCurve('out', 128, cur), t + 0.01, data.real.crossS);
    real.curveUntil = t + 0.01 + data.real.crossS;
    real.offAt = real.curveUntil + 0.5;
    real.ready = null;
    real.token++; // a track still being fetched is no longer wanted
    real.loading = null;
  }
  function teardownReal() {
    for (const e of real.entries) {
      if (e.ended) continue;
      e.ended = true;
      try {
        e.src.stop();
      } catch (err) {
        /* not started or already stopped */
      }
      activeSources--;
      free(e.src);
      free(e.g);
    }
    real.entries = [];
    if (real.out) free(real.out);
    real.out = null;
    real.ready = null;
    real.loading = null;
    real.token++;
    real.audibleSince = null;
    real.level = -1;
    real.curveUntil = -1;
    real.leaving = false;
    real.offAt = null;
  }
  function scheduleReal(t) {
    const wanted = style === 'real' && levels.music >= 0.05 && !real.failedAll;
    if (wanted) {
      if (real.leaving) {
        // the tracks were chosen again while they were falling: let the fall end (no click), then start afresh
        if (t >= real.curveUntil) teardownReal();
        return;
      }
      if (!trackLoadable()) return;
      if (!real.playlist) real.playlist = createPlaylist({ ids: data.real.tracks.map((x) => x.id), rng: mulberry32(Math.floor(rng() * 4294967296)) });
      const tail = real.entries[real.entries.length - 1];
      const due = !tail || t >= tail.start + tail.duration - tail.times.fadeOutS - data.real.preloadS;
      if (!real.ready && !real.loading && due) {
        if (real.playlist.left > 0) startLoad();
        else if (!tail) real.failedAll = true; // every track failed and none is playing: back to the generated style
      }
      if (real.ready) placeReady(t);
      if (real.out) applyRealLevel(t);
    } else if (real.out || real.loading || real.ready || real.entries.length) {
      if (!real.out) {
        teardownReal(); // still loading when the style was left: nothing was heard, nothing to fade
        return;
      }
      if (real.leaving) {
        if (t >= real.offAt) teardownReal();
        return;
      }
      if (style !== 'real' && real.audibleSince !== null && !genReady(t) && levels.music >= 0.05) return; // hold: the new style is not heard yet
      beginLeaveReal(t);
    } else if (real.failedAll && style !== 'real') {
      real.failedAll = false;
    }
  }

  function scheduleBirds(t) {
    if (levels.birds < 0.05 || t + data.lookaheadS < nextBird) return;
    const c = data.birds;
    const n = 2 + Math.floor(rng() * (c.chirps[1] - c.chirps[0] + 1));
    for (let i = 0; i < n; i++) {
      const at = t + 0.05 + i * (0.14 + rng() * 0.1);
      const dur = between(c.durS);
      const f0 = between(c.hz);
      const f1 = f0 * (0.7 + rng() * 0.8);
      if (tone({ hz: f0, hz2: Math.min(6000, Math.max(1200, f1)), at, attack: 0.01, hold: dur, decayTc: dur / 3, stop: at + dur + 0.15, peak: c.gain * levels.birds, dest: bus.ambience, forSfx: false })) counts.chirps++;
    }
    nextBird = t + between(c.everyS);
  }
  function scheduleMusic(t) {
    const c = data.music;
    // soft -> lofi: the soft notes go on until the first lofi bar is scheduled (at most 4 s), so that the two styles overlap instead of leaving a gap
    const crossing = genStyle() === 'lofi' && lofi.nextStart === null && styleChangedAt > -1e8 && t - styleChangedAt < 4;
    if (genStyle() !== 'soft' && !crossing) {
      // the echo is freed once its last notes have died away (nodes are precious: the lofi chain needs them)
      if (delay && notes.size === 0 && t - styleChangedAt > 6) {
        free(delay);
        free(feedback);
        delay = null;
        feedback = null;
      }
      return;
    }
    if (levels.music < 0.05 || t + data.lookaheadS < nextNote || notes.size >= c.maxNotes) return;
    if (!delay) {
      if (!room(4, false)) return;
      delay = track(ctx.createDelay(1));
      delay.delayTime.value = c.delayS;
      feedback = track(ctx.createGain());
      feedback.gain.value = c.feedback;
      delay.connect(feedback);
      feedback.connect(delay);
      delay.connect(bus.music);
    }
    if (!room(3, false)) return; // the note (oscillator + gain) and its send to the echo
    const scale = c.scales[levels.scale] || c.scales.dusk;
    const hz = scale[Math.floor(rng() * scale.length)];
    const at = Math.max(t, nextNote);
    const wet = track(ctx.createGain());
    wet.gain.value = c.wet;
    wet.connect(delay);
    const ok = tone({ type: rng() < 0.7 ? 'sine' : 'triangle', hz, at, attack: c.attackS, hold: c.attackS, decayTc: c.releaseS / 3, stop: at + c.attackS + c.releaseS * 1.5, peak: c.gain * levels.music, dest: bus.music, also: wet, forSfx: false });
    if (!ok) {
      free(wet);
      return;
    }
    // the wet send is freed with the note: find the note's oscillator through the gain's ended callback chain
    const token = {};
    notes.add(token);
    counts.notes++;
    setTimeoutLike(c.attackS + c.releaseS * 1.5 + 0.4, () => {
      notes.delete(token);
      free(wet);
    });
    nextNote = at + between(c.everyS);
  }
  /** Calls fn after s seconds of audio time (checked by the scheduler, so a suspended context waits). */
  const later = [];
  function setTimeoutLike(s, fn) {
    later.push({ at: now() + s, fn });
  }

  function tick() {
    if (!started || !ctx || ctx.state !== 'running') return;
    const t = now();
    ticked = true;
    for (let i = later.length - 1; i >= 0; i--) {
      if (later[i].at <= t) {
        const { fn } = later[i];
        later.splice(i, 1);
        fn();
      }
    }
    driveVoices(t);
    scheduleLofi(t); // before the birds: when nodes run short, a chirp is skipped, not a bar of music
    scheduleReal(t); // same for the recorded tracks
    scheduleBirds(t);
    scheduleMusic(t);
  }

  function setBus(name) {
    if (!started) return;
    bus[name].gain.setTargetAtTime(volumeGain(volumes[name]) * data.trim[name], now(), data.volumeTcS);
  }

  const engine = {
    get started() {
      return started;
    },
    get unavailable() {
      return unavailable;
    },
    get muted() {
      return muted;
    },
    /** Creates the context and the graph. MUST be called from a user gesture. Returns true when the sound is running or starting. */
    start() {
      if (started) return true;
      if (unavailable) return false;
      try {
        ctx = makeContext();
      } catch (e) {
        ctx = null;
      }
      if (!ctx) {
        unavailable = true;
        return false;
      }
      build();
      started = true;
      const t = now();
      master.gain.setValueAtTime(0, t);
      if (!muted) master.gain.linearRampToValueAtTime(1, t + data.masterFadeInS);
      if (!muted && !hidden && ctx.state === 'suspended') Promise.resolve(ctx.resume()).catch(() => {});
      if (muted) Promise.resolve(ctx.suspend()).catch(() => {});
      timer = timers.set(tick, data.tickMs);
      return true;
    },
    setMuted(m) {
      muted = !!m;
      if (!started) return;
      const t = now();
      master.gain.cancelScheduledValues(t);
      if (muted) {
        master.gain.setTargetAtTime(0, t, data.muteFadeS / 4);
        timers.after(() => {
          if (muted && ctx) Promise.resolve(ctx.suspend()).catch(() => {});
        }, Math.round(data.muteFadeS * 1000) + 100);
      } else {
        if (!hidden) Promise.resolve(ctx.resume()).catch(() => {});
        master.gain.setValueAtTime(master.gain.value, t);
        master.gain.setTargetAtTime(1, t + 0.02, 0.5);
      }
    },
    setVolume(name, v) {
      if (!(name in volumes)) return;
      volumes[name] = v;
      setBus(name);
    },
    setLevels(l) {
      levels = { ...levels, ...l };
    },
    /** 'soft' | 'lofi'. Before start() it only remembers the choice (no context is made). Changes cross-fade: nothing stops suddenly. */
    setStyle(name) {
      if (!data.styles.includes(name) || name === style) return;
      const heard = ctx && ticked;
      if (name === 'real') {
        real.base = heard ? style : null; // what was playing is kept until the tracks are ready (null: nothing was heard yet)
        real.failedAll = false;
        if (real.playlist) real.playlist.retry();
      } else if (style === 'real' && name === 'soft') nextNote = 0; // the notes come back at once while the tracks fall
      style = name;
      styleChangedAt = heard ? now() : -1e9;
    },
    get style() {
      return style;
    },
    sfx(name) {
      if (!started || muted || !ctx || ctx.state !== 'running') return;
      const fn = SFX[name];
      if (!fn) return;
      counts.sfx++;
      fn();
      if (name === 'catch' && genStyle() === 'lofi') duckLofi(data.lofi.duckS);
    },
    /** Tab hidden: suspend; shown again: resume (unless muted). */
    hide() {
      hidden = true;
      if (started) Promise.resolve(ctx.suspend()).catch(() => {});
    },
    show() {
      hidden = false;
      if (started && !muted) Promise.resolve(ctx.resume()).catch(() => {});
    },
    tick,
    analyser: () => tap,
    context: () => ctx,
    stats() {
      return {
        started,
        unavailable,
        muted,
        state: ctx ? ctx.state : 'none',
        nodes: alive.size,
        peakNodes,
        sources: activeSources,
        peakSources,
        voices: [...voices.keys()],
        style,
        lofi: { sources: lofi.sources.size, chain: !!lofi.gain, renderMsMax: lofiRenderMsMax, nextStart: lofi.nextStart, gain: lofi.last },
        real: {
          chain: !!real.out,
          entries: real.entries.map((e) => ({ id: e.id, start: e.start, duration: e.duration })),
          loading: real.loading,
          ready: real.ready ? real.ready.id : null,
          audible: real.audibleSince !== null,
          leaving: real.leaving,
          failedAll: real.failedAll,
          base: real.base,
          heardStyle: genStyle(),
          level: real.level,
          decodedBytesMax: real.decodedBytesMax,
          fetchMsMax: real.fetchMsMax,
          decodeMsMax: real.decodeMsMax,
          firstRequestAt: real.firstRequestAt,
        },
        volumes: { ...volumes },
        counts: { ...counts },
      };
    },
    dispose() {
      real.token++; // an answer that comes later is dropped
      if (timer !== null) timers.clear(timer);
      timer = null;
      if (ctx && ctx.close) Promise.resolve(ctx.close()).catch(() => {});
      started = false;
    },
  };
  return engine;
}
